const EXEC_SECRET_REF_ID_PATTERN=/^[A-Za-z0-9][A-Za-z0-9._:/#-]{0,255}$/;function parseVaultSecretId(e){const t=e.split(`/`);if(t.some(e=>e.length===0))throw new Error(`Vault SecretRef id "${e}" must not contain empty path segments.`);if(!EXEC_SECRET_REF_ID_PATTERN.test(e))throw new Error(`Vault SecretRef id "${e}" contains unsupported characters.`);if(t.length<2)throw new Error(`Vault SecretRef id "${e}" must use "<path>/<field>", for example "providers/openai/apiKey".`);if(t.some(e=>e===`.`||e===`..`))throw new Error(`Vault SecretRef id "${e}" must not contain dot path segments.`);return{secretPath:t.slice(0,-1).join(`/`),field:t.at(-1)}}export{parseVaultSecretId as t};